    """Convert raw output values into the appropriate Agent* type.

    If ``output_type`` is ``None`` we default to treating the output as text.
    This mirrors the common case where agents return plain strings.
    """
    # Default to text when no explicit type is provided
    if output_type is None:
        return AgentText(output)
    if output_type == "text":
